{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Test a modest reduction in the tied real-item embedding radius across all four category models. Preserve the vocabulary-dependent formula and raw mask embedding. The generated predictor imports this same model class, so training and inference remain consistent.",
      "edits": [
        {
          "find": "row_norm = 0.75 * math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))",
          "replace": "row_norm = 0.725 * math.sqrt(2.0 * self.hidden_units / (self.itemnum + 2 + self.hidden_units))"
        }
      ]
    }
  ],
  "change_summary": "Reduce only the shared tied real-item embedding radius multiplier from 0.75 to 0.725."
}
